// One short message from the no-reply address to the QYLAT mailbox. The poller reports seeing it.
// If it does not, the next sweep tells the owner that the mailbox may not be being read.
const cfg = $('Config').first().json;
const token = String($input.first().json.token || '');
return [{ json: { idempotency_key: 'qylat-inbox-check-' + token, payload: { from: cfg.alert_from, to: [cfg.mailbox], subject: cfg.canary_subject_prefix + ' ' + token, text: 'Automatic daily check that this mailbox is being read. Safe to delete.' } } }];

// Provider Outcome (n8n Code node, run once for each item). Shared by every step that hands an email
// to the sending provider. Only a 2xx answer carrying a message id counts as accepted. An answer that
// proves the provider refused the message is 'failed'. Anything else (timeout, network error, 5xx, 409)
// is 'uncertain': the email may have gone, so it is reported and never sent again automatically.
const res = $json || {};
const code = Number(res.statusCode);
const body = (res.body && typeof res.body === 'object') ? res.body : {};
let outcome = 'uncertain';
let providerId = '';
let error = '';
if (code >= 200 && code < 300 && body.id) {
  outcome = 'sent';
  providerId = String(body.id);
} else if ([400, 401, 403, 404, 405, 413, 422, 429].includes(code)) {
  outcome = 'failed';
  error = 'Provider ' + code + ': ' + String(body.message || body.name || 'rejected');
} else {
  error = code ? 'Provider ' + code + ': ' + String(body.message || 'no confirmation')
    : 'No response: ' + String((res.error && (res.error.message || res.error)) || 'unknown');
}
return { json: { outcome, provider_message_id: providerId, error: error.slice(0, 500) } };

// Build Sweep Alerts (n8n Code node, run once for all items).
// One short email per thing the sweep found. The sweep reports each thing once, changes states only,
// and never sends or resends a customer email.
const cfg = $('Config').first().json;
const TITLES = {
  stuck_processing: 'FAILED: a message was not processed',
  approval_expired: 'EXPIRED: a draft was not decided in time',
  send_uncertain: 'NOT KNOWN: a reply may or may not have been sent',
  deferred_message: 'Needs you: a second message was not answered',
  polling_stale: 'CHECK: the mailbox may not be being read',
};
const out = [];
for (const item of $input.all()) {
  const row = item.json || {};
  if (!row.kind || !TITLES[row.kind]) continue;
  const lines = [String(row.detail || '')];
  if (row.customer_email) lines.push('', 'From: ' + row.customer_email);
  if (row.subject) lines.push('Subject: ' + row.subject);
  if (row.kind !== 'polling_stale') lines.push('', 'Nothing was sent automatically and nothing will be. Read the mailbox and answer by hand if needed.');
  out.push({
    json: {
      kind: row.kind,
      thread_id: row.thread_id || null,
      draft_id: row.draft_id || null,
      idempotency_key: 'qylat-inbox-sweep-' + row.kind + '-' + String(row.draft_id || row.thread_id || new Date().toISOString().slice(0, 13)),
      payload: { from: cfg.alert_from, to: [cfg.owner_to], subject: '[QYLAT inbox] ' + TITLES[row.kind], text: lines.join('\n') },
    },
  });
}
return out;

